212:    /**
213:     * Inits the vhal configurations.
214:     *
215:     * <p><Note that {@link #getIfAvailableOrFailForEarlyStage(int, int)}
216:     * can be called before {@code init()}.
217:     */
218:    public void init() {
219:        fetchAllPropConfigs();
220:
221:        // PropertyHalService will take most properties, so make it big enough.
222:        ArrayMap<HalServiceBase, ArrayList<HalPropConfig>> configsForAllServices;
223:        synchronized (mLock) {
224:            configsForAllServices = new ArrayMap<>(mAllServices.size());
225:            for (int i = 0; i < mAllServices.size(); i++) {
226:                ArrayList<HalPropConfig> configsForService = new ArrayList();
227:                HalServiceBase service = mAllServices.get(i);
228:                configsForAllServices.put(service, configsForService);
229:                int[] supportedProps = service.getAllSupportedProperties();
230:                if (supportedProps.length == 0) {
231:                    for (int j = 0; j < mAllProperties.size(); j++) {
232:                        Integer propId = mAllProperties.keyAt(j);
233:                        if (service.isSupportedProperty(propId)) {
234:                            HalPropConfig config = mAllProperties.get(propId);
235:                            mPropertyHandlers.append(propId, service);
236:                            configsForService.add(config);
237:                        }
238:                    }
239:                } else {
240:                    for (int prop : supportedProps) {
241:                        HalPropConfig config = mAllProperties.get(prop);
242:                        if (config == null) {
243:                            continue;
244:                        }
245:                        mPropertyHandlers.append(prop, service);
246:                        configsForService.add(config);
247:                    }
248:                }
249:            }
250:        }
251:
252:        for (Map.Entry<HalServiceBase, ArrayList<HalPropConfig>> entry
253:                : configsForAllServices.entrySet()) {
254:            HalServiceBase service = entry.getKey();
255:            ArrayList<HalPropConfig> configsForService = entry.getValue();
256:            service.takeProperties(configsForService);
257:            service.init();
258:        }
259:    }
