261:    /**
262:     * Releases all connected services (power management service, input service, etc).
263:     */
264:    public void release() {
265:        ArrayList<Integer> subscribedProperties = new ArrayList<>();
266:        synchronized (mLock) {
267:            // release in reverse order from init
268:            for (int i = mAllServices.size() - 1; i >= 0; i--) {
269:                mAllServices.get(i).release();
270:            }
271:            for (int i = 0; i < mSubscribedProperties.size(); i++) {
272:                subscribedProperties.add(mSubscribedProperties.keyAt(i));
273:            }
274:            mSubscribedProperties.clear();
275:            mAllProperties.clear();
276:        }
277:        for (int i = 0; i < subscribedProperties.size(); i++) {
278:            try {
279:                mHalClient.unsubscribe(subscribedProperties.get(i));
280:            } catch (RemoteException | ServiceSpecificException e) {
281:                //  Ignore exceptions on shutdown path.
282:                Slogf.w(CarLog.TAG_HAL, "Failed to unsubscribe", e);
283:            }
284:        }
285:        // keep the looper thread as should be kept for the whole life cycle.
286:    }
