181:    public CarPropertyManager(Car car, @NonNull ICarProperty service) {
182:        super(car);
183:        mService = service;
184:        mAppTargetSdk = getContext().getApplicationInfo().targetSdkVersion;
185:
186:        Handler eventHandler = getEventHandler();
187:        if (eventHandler == null) {
188:            mHandler = null;
189:            return;
190:        }
191:        mHandler = new SingleMessageHandler<CarPropertyEvent>(eventHandler.getLooper(),
192:            MSG_GENERIC_EVENT) {
193:            @Override
194:            protected void handleEvent(CarPropertyEvent event) {
195:                CarPropertyListeners listeners;
196:                synchronized (mActivePropertyListener) {
197:                    listeners = mActivePropertyListener.get(
198:                        event.getCarPropertyValue().getPropertyId());
199:                }
200:                if (listeners != null) {
201:                    switch (event.getEventType()) {
202:                        case CarPropertyEvent.PROPERTY_EVENT_PROPERTY_CHANGE:
203:                            listeners.onPropertyChanged(event);
204:                            break;
205:                        case CarPropertyEvent.PROPERTY_EVENT_ERROR:
206:                            listeners.onErrorEvent(event);
207:                            break;
208:                        default:
209:                            throw new IllegalArgumentException();
210:                    }
211:                }
212:            }
213:        };
214:    }
