216:    /**
217:     * Register {@link CarPropertyEventCallback} to get property updates. Multiple listeners
218:     * can be registered for a single property or the same listener can be used for different
219:     * properties. If the same listener is registered again for the same property, it will be
220:     * updated to new rate.
221:     * <p>Rate could be one of the following:
222:     * <ul>
223:     *   <li>{@link CarPropertyManager#SENSOR_RATE_ONCHANGE}</li>
224:     *   <li>{@link CarPropertyManager#SENSOR_RATE_NORMAL}</li>
225:     *   <li>{@link CarPropertyManager#SENSOR_RATE_UI}</li>
226:     *   <li>{@link CarPropertyManager#SENSOR_RATE_FAST}</li>
227:     *   <li>{@link CarPropertyManager#SENSOR_RATE_FASTEST}</li>
228:     * </ul>
229:     * <p>
230:     * <b>Note:</b>Rate has no effect if the property has one of the following change modes:
231:     * <ul>
232:     *   <li>{@link CarPropertyConfig#VEHICLE_PROPERTY_CHANGE_MODE_STATIC}</li>
233:     *   <li>{@link CarPropertyConfig#VEHICLE_PROPERTY_CHANGE_MODE_ONCHANGE}</li>
234:     * </ul>
235:     * <b>Note:</b>If listener registers for updates for a
236:     * {@link CarPropertyConfig#VEHICLE_PROPERTY_CHANGE_MODE_ONCHANGE} property, it will receive the
237:     * property's current value upon registration.
238:     * See {@link CarPropertyConfig#getChangeMode()} for details.
239:     * If rate is higher than {@link CarPropertyConfig#getMaxSampleRate()}, it will be registered
240:     * with max sample rate.
241:     * If rate is lower than {@link CarPropertyConfig#getMinSampleRate()}, it will be registered
242:     * with min sample rate.
243:     *
244:     * @param callback CarPropertyEventCallback to be registered.
245:     * @param propertyId PropertyId to subscribe
246:     * @param rate how fast the property events are delivered in Hz.
247:     * @return true if the listener is successfully registered.
248:     * @throws SecurityException if missing the appropriate permission.
249:     */
250:    @AddedInOrBefore(majorVersion = 33)
251:    public boolean registerCallback(@NonNull CarPropertyEventCallback callback,
252:            int propertyId, @FloatRange(from = 0.0, to = 100.0) float rate) {
253:        synchronized (mActivePropertyListener) {
254:            if (mCarPropertyEventToService == null) {
255:                mCarPropertyEventToService = new CarPropertyEventListenerToService(this);
256:            }
257:            CarPropertyConfig config = getCarPropertyConfig(propertyId);
258:            if (config == null) {
259:                Log.e(TAG, "registerListener:  propId is not in config list:  " + propertyId);
260:                return false;
261:            }
262:            if (config.getChangeMode() == CarPropertyConfig.VEHICLE_PROPERTY_CHANGE_MODE_ONCHANGE) {
263:                rate = SENSOR_RATE_ONCHANGE;
264:            }
265:            boolean needsServerUpdate = false;
266:            CarPropertyListeners listeners;
267:            listeners = mActivePropertyListener.get(propertyId);
268:            if (listeners == null) {
269:                listeners = new CarPropertyListeners(rate);
270:                mActivePropertyListener.put(propertyId, listeners);
271:                needsServerUpdate = true;
272:            }
273:            if (listeners.addAndUpdateRate(callback, rate)) {
274:                needsServerUpdate = true;
275:            }
276:            if (needsServerUpdate) {
277:                if (!registerOrUpdatePropertyListener(propertyId, rate)) {
278:                    return false;
279:                }
280:            }
281:        }
282:        return true;
