877:        HashMap<Integer, VehiclePropValue> mMap = new HashMap<>();
878:        @Override
879:        public synchronized void onPropertySet(VehiclePropValue value) {
880:            // Simulate HalClient.set() behavior.
881:            int statusCode = mapPropertyToVhalStatusCode(value.prop);
882:            if (statusCode != VehicleHalStatusCode.STATUS_OK) {
883:                // The ServiceSpecificException here would pass the statusCode back to caller.
884:                throw new ServiceSpecificException(statusCode);
885:            }
886:
887:            mMap.put(value.prop, value);
888:        }
889:
890:        @Override
891:        public synchronized VehiclePropValue onPropertyGet(VehiclePropValue value) {
892:            // Simulate HalClient.get() behavior.
893:            int vhalStatusCode = mapPropertyToVhalStatusCode(value.prop);
894:            if (vhalStatusCode != VehicleHalStatusCode.STATUS_OK) {
895:                // The ServiceSpecificException here would pass the statusCode back to caller.
896:                throw new ServiceSpecificException(vhalStatusCode);
897:            }
898:
899:            int propertyStatus = mapPropertyToCarPropertyStatusCode(value.prop);
900:            if (value.prop == NULL_VALUE_PROP) {
901:                // Return null to simulate an unavailable property.
902:                // HAL implementation should return STATUS_TRY_AGAIN when a property is unavailable,
903:                // however, it may also return null with STATUS_OKAY and we want to handle this
904:                // properly.
905:                return null;
906:            }
907:            VehiclePropValue currentValue = mMap.get(value.prop);
908:            if (currentValue == null) {
909:                return value;
910:            } else {
911:                currentValue.status = propertyStatus;
912:            }
913:            return currentValue;
914:        }
